## 21_verify_report_claims.R -- independent recomputation of the descriptive and
## measurement numbers quoted in the report (RQ1/RQ2 chapters), straight from the cleaned data.
suppressPackageStartupMessages({ library(dplyr); library(psych); library(lavaan); library(readxl) })
root <- "/home/duc/Wildboar-Compensation-on-Tolerance"
df <- readRDS(file.path(root, "latest_analysis/output/models/clean_data_with_diagnostics.rds"))
raw <- read_excel(file.path(root, "data/3_Data.xlsx"), sheet = "Input Data")
sink(file.path(root, "latest_analysis/output/tables/140_verify_report_claims.txt"), split = TRUE)
cat("== SAMPLE ==\n"); cat("n =", nrow(df), "| raw columns =", ncol(raw), "\n"); print(table(df$county)); print(table(df$CE0)); print(table(df$county, df$CE0))
cat("Missing per raw column (non-zero only):\n"); print(colSums(is.na(raw))[colSums(is.na(raw)) > 0])
cat("\n== COUNTY x CE0 ==\n"); tb <- table(df$county, df$CE0)
print(chisq.test(tb)); print(chisq.test(tb, correct = FALSE)); ft <- fisher.test(tb); cat("Fisher p =", ft$p.value, " cond. OR =", ft$estimate, "\n")
cat("sample OR =", (tb["Baoxing","1"]/tb["Baoxing","0"])/(tb["Qingchuan","1"]/tb["Qingchuan","0"]), " Cramer V =", sqrt(chisq.test(tb, correct = FALSE)$statistic/nrow(df)), "\n")
print(round(chisq.test(tb)$expected, 1))
cat("\n== RANGES / OUT OF RANGE ==\n"); cat("hh_asset range:", range(df$hh_asset), "\n"); cat("CA1>1:", sum(df$CA1 > 1), " CA2>1:", sum(df$CA2 > 1), " max:", max(df$CA1), max(df$CA2), "\n")
cat("IC2_2 zeros:", sum(raw$IC2_2 == 0), " IC2_3 zeros:", sum(raw$IC2_3 == 0), "\n")
cat("\n== TOLERANCE RELIABILITY ==\n")
t4 <- df[, c("Tol1_5","Tol2_1","Tol3_1","Tol4_5")]; t3 <- t4[, -3]
a4 <- psych::alpha(t4, check.keys = FALSE); a3 <- psych::alpha(t3, check.keys = FALSE)
cat("alpha 4-item:", a4$total$raw_alpha, " 3-item:", a3$total$raw_alpha, "\n")
cat("4-item item statistics (r.drop = correlation with sum of the OTHER items; r.cor = corrected for overlap+reliability):\n"); print(round(a4$item.stats[, c("raw.r","r.cor","r.drop")], 3))
cat("manual r.drop check:", sapply(1:4, function(i) round(cor(t4[[i]], rowSums(t4[, -i])), 3)), "\n")
cat("3-item r.drop:\n"); print(round(a3$item.stats[, c("raw.r","r.cor","r.drop")], 3))
pc <- polychoric(t3)$rho; k <- 3; rbar <- mean(pc[lower.tri(pc)]); cat("ordinal alpha (polychoric), 3-item:", k*rbar/(1+(k-1)*rbar), "\n"); cat("polychoric correlations, 4 items:\n"); print(round(polychoric(t4)$rho, 3))
cat("Pearson correlations, 4 items:\n"); print(round(cor(t4), 3))
cat("\n== EFA 1 factor, 4 items ==\n"); print(round(unclass(fa(t4, nfactors = 1, fm = "ml")$loadings), 3))
cat("\n== CFA (ordinal WLSMV), 4 items ==\n")
f4 <- cfa('Tol =~ Tol1_5 + Tol2_1 + Tol3_1 + Tol4_5', data = df, ordered = names(t4), estimator = "WLSMV")
print(subset(standardizedSolution(f4), op == "=~")[, c("rhs","est.std","se","z","pvalue")], digits = 3)
cat("Heywood check - model-implied residual variances (1 - loading^2):\n"); print(round(1 - subset(standardizedSolution(f4), op == "=~")$est.std^2, 3))
cat("\n== CFA (continuous, robust ML), 4 items -- does the Tol3 conclusion survive without the improper solution? ==\n")
f4c <- cfa('Tol =~ Tol1_5 + Tol2_1 + Tol3_1 + Tol4_5', data = df, estimator = "MLR")
print(subset(standardizedSolution(f4c), op == "=~")[, c("rhs","est.std","se","z","pvalue")], digits = 3)
print(subset(parameterEstimates(f4c), op == "~~" & lhs == rhs)[, c("lhs","est","se")], digits = 3)
cat("\n== CFA ordinal with Tol2 residual variance constrained (loading <= 1 via equal loadings Tol1=Tol2) ==\n")
f4e <- cfa('Tol =~ a*Tol1_5 + a*Tol2_1 + Tol3_1 + Tol4_5', data = df, ordered = names(t4), estimator = "WLSMV", std.lv = TRUE)
print(subset(standardizedSolution(f4e), op == "=~")[, c("rhs","est.std","se","z","pvalue")], digits = 3)
cat("\n== INTANGIBLE COST block ==\n"); ic <- df[, c("IC1","IC2_1","IC2_2_imp","IC2_3_imp")]; print(KMO(ic)$MSA)
pa <- fa.parallel(ic, fm = "ml", fa = "fa", plot = FALSE, n.iter = 200); cat("parallel analysis nfact:", pa$nfact, "\n")
cat("\n== MAHALANOBIS ==\n"); cat("flagged p<.001:", sum(df$maha_p < .001, na.rm = TRUE), "of", nrow(df), "\n")
sink()
